            align-items: center;
            justify-content: space-between;
            width: 100%;
            gap: 16px;
            flex-wrap: wrap;
        }
        .title-area {
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .title-icon {
            font-size: 2rem;
            animation: bounceIcon 1.2s ease-in-out infinite;
        }
        @keyframes bounceIcon {
            0%,
            100% {
                transform: translateY(0);
            }
            30% {
                transform: translateY(-8px);
            }
            50% {
                transform: translateY(0);
            }
            70% {
                transform: translateY(-4px);
            }
        }
        .title {
            font-size: 1.6rem;
            font-weight: 700;
            color: var(--text);
            letter-spacing: 0.04em;
            background: linear-gradient(135deg, #00ff88, #00ddcc);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .score-panel {
            display: flex;
            align-items: center;
            gap: 12px;
            background: rgba(255, 255, 255, 0.03);
            border: 1px solid var(--border);
            border-radius: 40px;
            padding: 8px 20px;
        }
        .score-label {
            font-size: 0.85rem;
            color: #888;
            letter-spacing: 0.06em;
            text-transform: uppercase;
        }
        .score-value {
            font-size: 1.5rem;
            font-weight: 700;
            color: #00ff88;
            text-shadow: var(--glow);
            min-width: 50px;
            text-align: center;
            transition: all 0.2s;
        }
        .score-value.pulse {
            animation: scorePulse 0.4s ease-out;
        }
        @keyframes scorePulse {
            0% {
                transform: scale(1.4);
                color: #fff;
            }
            100% {
                transform: scale(1);
                color: #00ff88;
            }
        }
        .best-score {
            font-size: 0.8rem;
            color: #666;
        }
        .best-score span {
            color: #ffaa44;
            font-weight: 600;
        }

        .canvas-container {
