            box-shadow:
                inset 0 0 30px rgba(0, 0, 0, 0.4),
                0 0 0 3px rgba(255, 255, 255, 0.5),
                0 0 30px rgba(255, 255, 255, 0.2);
        }
        canvas {
            display: block;
            background: #0d0d18;
            border-radius: 14px;
        }

        .overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            pointer-events: none;
            border-radius: 14px;
            transition: background 0.3s;
        }
        .overlay.active {
            background: rgba(0, 0, 0, 0.7);
            pointer-events: auto;
        }
        .overlay-text {
            font-size: 2.5rem;
            font-weight: 800;
            color: #ff4466;
            text-shadow: var(--glow-red);
            letter-spacing: 0.06em;
            display: none;
        }
        .overlay.active .overlay-text {
            display: block;
            animation: shakeText 0.5s ease-out;
        }
        @keyframes shakeText {
            0%,
            100% {
                transform: translateX(0);
            }
            20% {
                transform: translateX(-6px);
            }
            40% {
                transform: translateX(6px);
            }
            60% {
                transform: translateX(-4px);
            }
            80% {
                transform: translateX(4px);
            }
        }
        .overlay-sub {
            font-size: 1rem;
            color: #ccc;
            margin-top: 8px;
            display: none;
        }
        .overlay.active .overlay-sub {
            display: block;
        }
        .overlay-hint {
            font-size: 0.9rem;
            color: #aaa;
            margin-top: 14px;
            display: none;
            animation: fadeInUp 0.6s ease-out 0.3s both;
        }
        .overlay.active .overlay-hint {
            display: block;
        }
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .controls {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
            justify-content: center;
            align-items: center;
        }
        .btn {
            padding: 10px 22px;
            border-radius: 30px;
            border: 1px solid var(--border);
            background: rgba(255, 255, 255, 0.04);
            color: var(--text);
            cursor: pointer;
            font-size: 0.95rem;
            font-weight: 500;
            letter-spacing: 0.03em;
            transition: all 0.25s;
            backdrop-filter: blur(4px);
            white-space: nowrap;
        }
        .btn:hover {
            background: rgba(255, 255, 255, 0.08);
            border-color: #00ff88;
            box-shadow: 0 0 16px rgba(0, 255, 136, 0.2);
            transform: translateY(-1px);
        }
        .btn:active {
            transform: scale(0.96);
            transition: transform 0.1s;
        }
        .btn.primary {
            background: #00ff88;
            color: #000;
            border-color: #00ff88;
            font-weight: 700;
            box-shadow: 0 0 20px rgba(0, 255, 136, 0.35);
        }
        .btn.primary:hover {
            background: #00ee77;
            box-shadow: 0 0 30px rgba(0, 255, 136, 0.5);
        }
        .btn.danger {
            border-color: #ff4466;
            color: #ff4466;
        }
        .btn.danger:hover {
            background: rgba(255, 68, 102, 0.1);
            box-shadow: 0 0 16px rgba(255, 68, 102, 0.25);
        }
        .difficulty-badge {
            font-size: 0.75rem;
            padding: 5px 12px;
            border-radius: 20px;
            background: rgba(255, 170, 68, 0.15);
            color: #ffaa44;
            border: 1px solid rgba(255, 170, 68, 0.3);
            font-weight: 500;
            cursor: pointer;
            transition: all 0.25s;
        }
        .difficulty-badge:hover {
            background: rgba(255, 170, 68, 0.25);
        }

        /* 移动端方向键 */
        .mobile-dpad {
