            -webkit-tap-highlight-color: transparent;
        }
        .dpad-btn:active {
            background: rgba(0, 255, 136, 0.25);
            border-color: #00ff88;
            box-shadow: 0 0 12px rgba(0, 255, 136, 0.3);
            transform: scale(0.9);
        }
        .dpad-up {
            grid-area: up;
        }
        .dpad-down {
            grid-area: down;
        }
        .dpad-left {
            grid-area: left;
        }
        .dpad-right {
            grid-area: right;
        }

        @media (max-width: 520px) {
            .game-wrapper {
                padding: 14px 10px 12px;
                border-radius: 18px;
                gap: 10px;
            }
            .title {
                font-size: 1.3rem;
            }
            .score-value {
                font-size: 1.2rem;
            }
            .btn {
                padding: 8px 14px;
                font-size: 0.8rem;
            }
            .mobile-dpad {
                display: grid;
            }
            canvas {
                border-radius: 10px;
            }
            .overlay-text {
                font-size: 2rem;
            }
        }
        @media (min-width: 521px) {
